(async () => {
  if (!canvas.ready) { ui.notifications.error('Canvas not ready'); return; }
  const scene = canvas.scene;
  if (!scene) { ui.notifications.error('No active scene'); return; }

  const selectedTokens = canvas.tokens.controlled;
  if (selectedTokens.length === 0) { ui.notifications.error('Please select a token first'); return; }

  const selectedToken = selectedTokens[0];
  if (!selectedToken.isOwner) { ui.notifications.error('You do not own this token'); return; }

  // Inline flag helpers — FollowManager is bundled into the system and cannot be imported
  const getRelationships = (sc) => {
    const r = sc.getFlag('nimble', 'followRelationships');
    return Array.isArray(r) ? r : [];
  };
  const setRelationships = (sc, rels) => sc.setFlag('nimble', 'followRelationships', rels);

  const relationships = getRelationships(scene);
  const asFollower = relationships.find(r => r.followerId === selectedToken.id);

  if (asFollower) {
    const leaderToken = scene.tokens.get(asFollower.leaderId);
    const leaderName = leaderToken?.name ?? 'Unknown Token';
    const content = `<p><strong>${selectedToken.name}</strong> is currently following <strong>${leaderName}</strong> at a distance of <strong>${asFollower.distance}</strong> grid squares.</p><p>Do you want to clear this follow link?</p>`;

    new Dialog({
      title: `Clear Follow Link – ${selectedToken.name}`,
      content,
      buttons: {
        clear: {
          label: '\uD83D\uDD17 Clear Follow',
          callback: async () => {
            const rels = getRelationships(scene);
            const filtered = rels.filter(r => r.followerId !== selectedToken.id);
            if (filtered.length < rels.length) {
              await setRelationships(scene, filtered);
              const lt = scene.tokens.get(asFollower.leaderId);
              const ln = lt?.name ?? 'Unknown Token';
              ChatMessage.create({ content: `<p><strong>${selectedToken.name}</strong> is no longer following <strong>${ln}</strong>.</p>`, flavor: '\uD83D\uDD17 Follow Link Cleared' });
              ui.notifications.info(`${selectedToken.name} is no longer following any tokens`);
            } else {
              ui.notifications.warn('Failed to clear follow link');
            }
          }
        },
        cancel: { label: 'Cancel', callback: () => {} }
      },
      default: 'cancel'
    }).render(true);
  } else {
    new Dialog({
      title: `Create Follow Link – ${selectedToken.name}`,
      content: `<p>Select a second token alongside <strong>${selectedToken.name}</strong>, then click Create Link. That second token becomes the leader.</p><p><em>The follow distance will be set from current positions.</em></p>`,
      buttons: {
        create: {
          label: '\uD83D\uDD17 Create Link',
          callback: async () => {
            const targetTokens = canvas.tokens.controlled.filter(t => t.id !== selectedToken.id);
            if (targetTokens.length === 0) { ui.notifications.error('Select a second token to follow'); return; }
            const targetToken = targetTokens[0];
            if (!targetToken.isOwner) { ui.notifications.error(`You do not own ${targetToken.name}`); return; }
            if (!canvas.grid) { ui.notifications.error('Grid system not available'); return; }

            const distance = canvas.grid.measureDistance(
              { x: selectedToken.x, y: selectedToken.y },
              { x: targetToken.x, y: targetToken.y }
            );

            const rels = getRelationships(scene);
            const newRel = { leaderId: targetToken.id, followerId: selectedToken.id, distance, timestamp: Date.now() };
            const existingIdx = rels.findIndex(r => r.leaderId === targetToken.id && r.followerId === selectedToken.id);
            if (existingIdx >= 0) { rels[existingIdx] = newRel; } else { rels.push(newRel); }
            await setRelationships(scene, rels);

            ChatMessage.create({ content: `<p><strong>${selectedToken.name}</strong> will now follow <strong>${targetToken.name}</strong> at a distance of <strong>${distance.toFixed(1)}</strong> grid squares.</p>`, flavor: '\uD83D\uDD17 Follow Link Created' });
            ui.notifications.info(`Follow link created: ${selectedToken.name} \u2192 ${targetToken.name}`);
          }
        },
        cancel: { label: 'Cancel', callback: () => {} }
      },
      default: 'cancel'
    }).render(true);
  }
})();
